@@ -1,24 +1,24 @@
-import { isPrUrl } from "../pr-url.js";
+import { isPrUrl, PR_URL_EXPECTED } from "../pr-url.js";
@@ -155,40 +155,80 @@ function trimUrl(url: string): string {
+export function normalizeTypedLink(link: TaskLink): TaskLink {
+  if (/\r|\n/.test(link.url)) {
+    throw new AxiError("Task link must be a single line", "VALIDATION_ERROR");
+  }
+  const normalized = link.url.trim();
+  if (normalized === "") {
+    throw new AxiError("Task link must not be empty", "VALIDATION_ERROR");
+  }
+  const url = link.kind === "pr" ? link.url : normalized;
+  if (
+    !deriveLinks(url).some(
+      (candidate) => candidate.kind === link.kind && candidate.url === url,
+    )
+  ) {
+    const expected =
+      link.kind === "pr"
+        ? PR_URL_EXPECTED
+        : link.kind === "report"
+          ? "a data/<id>/report.md path"
+          : "an http(s) URL";
+    throw new AxiError(
+      `Task ${link.kind} link must be ${expected}`,
+      "VALIDATION_ERROR",
+    );
+  }
+  return { kind: link.kind, url };
+}
+
+export function normalizeTypedLinks(links: TaskLink[]): TaskLink[] {
+  const normalized: TaskLink[] = [];
+  const seen = new Set<string>();
+  for (const link of links) {
+    const next = normalizeTypedLink(link);
+    if (seen.has(next.url)) continue;
+    seen.add(next.url);
+    normalized.push(next);
+  }
+  return normalized;
+}
+
