	return typeof value === "string" && value.length >= 10
		? value.slice(0, 10)
		: undefined;
}

function str(value: unknown): string | undefined {
	return typeof value === "string" && value !== "" ? value : undefined;
}

function parseTags(raw: unknown): string[] {
	return typeof raw === "string"
