		error = new AxiError(message, "CONFLICT");
	} else if (status === 400) {
		error = new AxiError(message, "VALIDATION_ERROR");
	} else {
		error = new AxiError(
			`Azure DevOps request failed (${status}): ${message}`,
			"UNKNOWN",
		);
	}
	return status >= 400 && status < 500 ? definitive(error) : error;
}

