	backend?: string;
	file?: string;
	cwd?: string;
	home?: string;
	env?: NodeJS.ProcessEnv;
}

interface TomlConfig {
	backend?: string;
	markdown?: {
		path?: string;
		archive?: string;
		done_keep?: number;
	};
	ado?: string[];
}

interface RawTomlConfig {
	backend?: string;
	markdown?: string[];
	ado?: string[];
